          desktop.textSamples.map(
            ({ responsiveCaptionTitle }) => responsiveCaptionTitle,
          ),
        );
        const desktopCaptionTitles = desktop.textSamples.filter(
          ({ responsiveCaptionTitle }) => responsiveCaptionTitle,
